  ('"Don\'t worry about the test. It\'ll be a piece of cake." Bu cümlede sınav için ne söylenmektedir?', 'Çok kolay olacak.', ['Çok uzun sürecek.', 'Sonunda ödül verilecek.', 'Başka bir güne ertelenecek.'], '\'A piece of cake\' çok kolay bir şey anlamına gelen bir deyimdir.'),
  ('"Can you keep an eye on my bag while I buy a coffee?" Konuşan kişi ne istiyor?', 'Çantasına göz kulak olunmasını', ['Çantasının hemen açılıp bakılmasını', 'Çantasının eve taşınmasını', 'Çantasının ucuza satılmasını'], '\'Keep an eye on\' bir şeye göz kulak olmak, gözetmek demektir.'),
  ('"She was over the moon when she won the scholarship." Cümlesine göre kız nasıl hissetti?', 'Çok mutlu oldu.', ['Biraz şaşırdı.', 'Çok korktu.', 'Hayal kırıklığına uğradı.'], '\'Over the moon\' son derece mutlu, havalara uçmuş demektir.'),
  ('Hangi deyim \'aşırı yağmur yağıyor\' anlamına gelir?', 'It\'s raining cats and dogs.', ['It\'s a piece of cake.', 'Hold your horses, please.', 'Once in a blue moon.'], '\'It\'s raining cats and dogs\' bardaktan boşanırcasına yağmur yağdığını anlatır.'),
  ('"After her best friend moved to another city, Elif felt very ____ because she had nobody to talk to." Boşluğa hangisi gelir?', 'lonely', ['proud', 'relaxed', 'amused'], 'Konuşacak kimsesi olmayan kişi kendini yalnız hisseder: \'lonely\'. \'Proud\' gururlu, \'amused\' eğlenmiş demektir.'),
  ('"I\'m ____ of spiders; I scream when I see one." Boşluğa hangisi gelir?', 'scared', ['proud', 'fond', 'exhausted'], '\'Be scared of\' bir şeyden korkmak demektir; çığlık atmak da korkuyu gösterir.'),
  ('Hastanede hastalara ilaç veren, ateşini ölçen ve doktora yardımcı olan kişinin mesleği hangisidir?', 'nurse', ['surgeon', 'pharmacist', 'dentist'], 'Hasta bakımını üstlenen sağlık çalışanı \'nurse\' (hemşire) dir. \'Pharmacist\' eczacı, \'surgeon\' cerrah demektir.'),
  ('"My uncle designs buildings and bridges." Cümlesine göre amcanın mesleği hangisi olabilir?', 'architect', ['plumber', 'lawyer', 'shop assistant'], 'Bina tasarlayan kişi \'architect\' (mimar) tır.'),
  ('"She works for a newspaper and writes articles about politics." Cümlesindeki kişinin mesleği hangisidir?', 'journalist', ['librarian', 'receptionist', 'accountant'], 'Gazetede haber ve makale yazan kişi \'journalist\' (gazeteci) dir.'),
  ('"The ____ checked my teeth and said I needed a filling." Boşluğa hangisi gelir?', 'dentist', ['vet', 'optician', 'pilot'], 'Dişleri muayene eden kişi \'dentist\' (diş hekimi) tir. \'Vet\' veteriner, \'optician\' gözlükçüdür.'),
  ('"Our flight was delayed because of the fog." Cümlesinde \'delayed\' ne anlama gelir?', 'rötar yaptı, gecikti', ['iptal edildi', 'planlanandan erken kalktı', 'yön değiştirdi'], '\'Delayed\' ertelenmiş, gecikmiş demektir; iptal için \'cancelled\' kullanılır.'),
  ('Yurt dışına çıkarken kimlik belgesi olarak gösterilen ve ülkelerin damga bastığı belge hangisidir?', 'passport', ['boarding pass', 'receipt', 'driving licence'], 'Yurt dışı yolculuklarda kimlik belgesi \'passport\' tır. \'Boarding pass\' biniş kartıdır.'),
  ('"I have a terrible ____; I think I ate too much chocolate." Boşluğa hangisi gelir?', 'stomachache', ['toothbrush', 'sunburn', 'headphones'], 'Çok çikolata yemenin sonucu karın ağrısıdır: \'stomachache\'.'),
  ('Vücudumuzda kanı pompalayan organ hangisidir?', 'heart', ['lungs', 'liver', 'kidney'], 'Kanı pompalayan organ \'heart\' (kalp) tir. \'Lungs\' akciğerler, \'liver\' karaciğer, \'kidney\' böbrektir.'),
  ('\'Elbow\' sözcüğü vücudun hangi bölümünü anlatır?', 'dirsek', ['diz', 'bilek', 'omuz başı'], '\'Elbow\' dirsek demektir; diz \'knee\', bilek \'wrist\', omuz \'shoulder\' dır.'),
  ('"Factories and cars cause air ____." Boşluğa \'kirlilik\' anlamında hangisi gelir?', 'pollution', ['population', 'production', 'protection'], '\'Pollution\' kirlilik demektir; \'population\' nüfus, \'protection\' koruma anlamına gelir.'),
  ('Kâğıt, cam ve plastik atıkların yeniden işlenip kullanılmasına İngilizcede ne denir?', 'recycling', ['reducing waste', 'rebuilding', 'refilling bottles'], 'Atıkların yeniden işlenmesi \'recycling\' (geri dönüşüm) dür.'),
  ('Hangi sözcük \'sel, taşkın\' anlamına gelir?', 'flood', ['flow', 'fold', 'flooring'], '\'Flood\' sel demektir; \'flow\' akmak, \'floor\' zemin anlamındadır.'),
  ('"Please ____ the file before you close the program, or you will lose your work." Boşluğa hangisi gelir?', 'save', ['delete', 'print', 'search'], 'Programı kapatmadan önce çalışmanın kaybolmaması için dosya kaydedilir: \'save\'.'),
  ('Bir bilgisayar ya da telefonu internete bağlamadan tek başına yapılan işlemleri anlatan sözcük hangisidir?', 'offline', ['online', 'download', 'upload'], '\'Offline\' çevrimdışı demektir; \'online\' çevrimiçidir.'),
  ('Bir web sitesine girerken kullanıcı adınızla birlikte yazdığınız gizli sözcüğe ne denir?', 'password', ['username', 'keyboard', 'screen saver'], 'Gizli giriş sözcüğü \'password\' (parola) dır.'),
  ('"My phone\'s ____ is low; I need to charge it." Boşluğa hangisi gelir?', 'battery', ['charger', 'signal', 'screen saver'], 'Şarjı azalan şey bataryadır: \'battery\'. \'Charger\' şarj aletidir.'),
  ('Okulda öğrencilerin dersler arasında dinlendiği kısa zaman dilimine İngilizcede ne denir?', 'break', ['term', 'degree', 'timetable'], 'Teneffüs \'break\' tir. \'Term\' dönem, \'timetable\' ders programıdır.'),
  ('\'Subject\' sözcüğü okul bağlamında hangi anlamdadır?', 'ders, branş', ['sınıf, şube', 'not, puan', 'sıra, masa, sandalye'], 'Okulda \'subject\' matematik, tarih gibi ders anlamına gelir.'),
  ('"Could you ____ the onions into small pieces?" Boşluğa doğramak anlamında hangisi gelir?', 'chop', ['pour', 'stir', 'sprinkle'], '\'Chop\' doğramak demektir. \'Pour\' dökmek, \'stir\' karıştırmak, \'melt\' eritmektir.'),
  ('Lokantada yemeğin sonunda garsondan istenen hesap pusulasına İngiliz İngilizcesinde ne denir?', 'the bill', ['the menu', 'the tip', 'the order'], 'Hesap \'bill\' tir. \'Tip\' garsona bırakılan bahşiştir.'),
  ('"This soup is too ____; you put in too much salt." Boşluğa hangisi gelir?', 'salty', ['sweet', 'sour', 'bitter-sweet'], 'Çok tuz konmuş yemek \'salty\' (tuzlu) dir; \'sour\' ekşi, \'spicy\' baharatlı/acıdır.'),
  ('"I\'m a vegetarian, so I don\'t eat ____." Boşluğa hangisi gelir?', 'meat', ['vegetables', 'fruit', 'bread'], 'Vejetaryenler et yemez: \'meat\'.'),
  ('Yemeklerin bulaşıklarını yıkamak için kullanılan mutfak aletine ne denir?', 'dishwasher', ['washing machine', 'cooker', 'freezer'], 'Bulaşık makinesi \'dishwasher\', çamaşır makinesi \'washing machine\' dır.'),
  ('"The ____ is broken, so we have to climb the stairs to the tenth floor." Boşluğa hangisi gelir?', 'lift', ['staircase', 'doorbell', 'roof'], 'Merdiven çıkmak zorunda kalınması asansörün bozulduğunu gösterir: \'lift\' (Amerikan İngilizcesinde \'elevator\').'),
  ('\'Pillow\' sözcüğü ne anlama gelir?', 'yastık', ['battaniye', 'çarşaf', 'halı'], '\'Pillow\' yastık demektir; battaniye \'blanket\', çarşaf \'sheet\', halı \'carpet\' tır.'),
  ('"Can you turn on the ____? It\'s getting dark in here." Boşluğa en uygun sözcük hangisidir?', 'lamp', ['tap', 'oven', 'kitchen sink'], 'Karanlıkta açılan şey lambadır: \'lamp\'. \'Tap\' musluk, \'sink\' lavabodur.'),
  ('Evin önünde ya da arkasında çiçek ve sebze yetiştirilen alana ne denir?', 'garden', ['garage', 'hall', 'landing'], 'Bahçe \'garden\' dır. \'Garage\' araba garajı, \'hall\' giriş holüdür.'),
  ('"It\'s ____ today; take an umbrella." Boşluğa hangisi gelir?', 'rainy', ['sunny', 'dry', 'windless'], 'Şemsiye gerektiren hava yağmurludur: \'rainy\'.'),
  ('Hangi sözcük \'sis\' anlamına gelir?', 'fog', ['frost', 'flash', 'fall'], '\'Fog\' sis, \'frost\' kırağı/don demektir.'),
