  ('Gökyüzünde güneş ve yağmur birlikteyken oluşan renkli yaya İngilizcede ne denir?', 'rainbow', ['raindrop', 'rainfall', 'rainforest'], 'Gökkuşağı \'rainbow\' dur. \'Rainforest\' yağmur ormanıdır.'),
  ('"It\'s freezing outside; the lake is covered with ____." Boşluğa hangisi gelir?', 'ice', ['steam', 'mud', 'dust'], 'Dondurucu soğukta gölün yüzeyi buzla kaplanır: \'ice\'.'),
  ('"He always tells the truth and never steals." Cümlesi kişinin hangi özelliğini anlatır?', 'honest', ['lazy', 'shy', 'rude and unkind'], 'Her zaman doğruyu söyleyen ve çalmayan kişi dürüsttür: \'honest\'.'),
  ('Yeni insanlarla tanışmaktan çekinen, kalabalıkta az konuşan biri için hangisi kullanılır?', 'shy', ['bossy', 'outgoing', 'talkative'], 'Utangaç kişi \'shy\' tır. \'Outgoing\' dışa dönük, \'talkative\' konuşkan demektir.'),
  ('"Kerem is so ____; he always makes everyone laugh with his jokes." Boşluğa hangisi gelir?', 'funny', ['serious', 'gloomy', 'nervous'], 'Herkesi güldüren kişi komiktir: \'funny\'.'),
  ('\'Tiny\' sözcüğü hangi sıfatın aşırı biçimidir?', 'small', ['thin', 'short', 'younger'], '\'Tiny\' çok küçük demektir; \'small\' sözcüğünün aşırı biçimidir.'),
  ('Aşağıdaki sözcüklerden hangisi meyve grubuna girmez?', 'carrot', ['apple', 'pineapple', 'cherry'], 'Havuç (carrot) bir sebzedir; diğerleri meyvedir.'),
  ('Aşağıdaki hayvanlardan hangisi kedigiller ailesinden değildir?', 'eagle', ['lion', 'tiger', 'leopard'], 'Kartal (eagle) bir kuştur; diğerleri kedigiller ailesinden memelilerdir.'),
  ('Aşağıdakilerden hangisi bir mutfak eşyası değildir?', 'screwdriver', ['saucepan', 'frying pan', 'electric kettle'], 'Tornavida (screwdriver) bir el aletidir; diğerleri mutfak eşyasıdır.'),
  ('\'Puppy\' sözcüğü hangi hayvanın yavrusudur?', 'köpek', ['kedi', 'inek', 'koyun'], '\'Puppy\' köpek yavrusudur. Kedi yavrusu \'kitten\', inek yavrusu \'calf\', koyun yavrusu \'lamb\' dır.'),
  ('\'Bookshop\' birleşik isminin Türkçe karşılığı hangisidir?', 'kitapçı', ['kütüphane', 'kitaplık rafı', 'yayınevi'], '\'Bookshop\' kitap satılan dükkândır; kütüphane \'library\', yayınevi \'publisher\' dır.'),
  ('\'Traffic jam\' ifadesi ne anlama gelir?', 'trafik sıkışıklığı', ['trafik ışığı', 'trafik cezası', 'trafik polisi ve görevlisi'], '\'Traffic jam\' araçların sıkışıp ilerleyemediği trafik tıkanıklığıdır.'),
  ('Hangi birleşik isim \'doğum günü\' anlamına gelir?', 'birthday', ['birthplace', 'birth rate', 'date of birth'], '\'Birthday\' doğum günüdür. \'Birthplace\' doğum yeri, \'birth rate\' doğum oranı, \'date of birth\' doğum tarihidir.'),
  ('"Don\'t forget to bring your ____; we\'ll swim in the hotel pool." Boşluğa hangisi gelir?', 'swimsuit', ['sweatshirt', 'suitcase', 'sunflower'], 'Havuzda yüzmek için mayo gerekir: \'swimsuit\'.'),
  ('"Can you book a table for four at the restaurant?" Cümlesinde \'book\' hangi anlamdadır?', 'rezervasyon yapmak', ['kitap okumak', 'yazmak, kaydetmek', 'peşin ödeme yapmak'], 'Fiil olarak \'book\' yer ayırtmak, rezervasyon yapmak demektir.'),
  ('\'Kids\' sözcüğünün resmî dildeki karşılığı hangisidir?', 'children', ['teenagers', 'students', 'relatives'], '\'Kids\' gündelik dilde çocuklar demektir; resmî karşılığı \'children\' dır.'),
  ('"She has ____ hair that reaches her waist." Boşluğa hangisi gelir?', 'long', ['tall', 'high', 'large'], 'Saç için \'long\' kullanılır; \'tall\' insanlar ve binalar için kullanılır.'),
  ('Futbolda maçı yöneten ve kurallara uyulmasını sağlayan kişi kimdir?', 'referee', ['coach', 'goalkeeper', 'captain'], 'Hakem \'referee\' dir. \'Coach\' antrenör, \'goalkeeper\' kaleci demektir.'),
  ('"You should avoid eating too much sugar." Cümlesindeki \'avoid\' fiilinin anlamı hangisidir?', 'kaçınmak', ['tercih etmek', 'sevmek', 'denemek'], '\'Avoid\' bir şeyden uzak durmak, kaçınmak demektir.'),
  ('"The guests complained about the cold food." Cümlesine göre konuklar ne yaptı?', 'Yemeklerden şikâyet ettiler.', ['Yemekleri çok beğendiler.', 'Yemekleri ısıttılar.', 'Yemekleri geri gönderdiler ve teşekkür ettiler.'], '\'Complain about\' bir şeyden şikâyet etmek demektir.'),
  ('"My cousin has been living abroad for five years." Cümlesindeki \'abroad\' ne anlama gelir?', 'yurt dışında', ['köyde', 'yalnız', 'yatılı okulda'], '\'Abroad\' yabancı bir ülkede, yurt dışında demektir.'),
  ('"The storm caused serious damage to the roofs." Cümlesinde \'damage\' sözcüğünün anlamı hangisidir?', 'hasar', ['gürültü', 'temizlik', 'sıcaklık'], '\'Damage\' hasar, zarar demektir.'),
  ('"This film is not suitable for young children; it\'s too violent." Cümlesindeki \'suitable\' ne anlama gelir?', 'uygun', ['pahalı', 'ilginç', 'uzun'], '\'Suitable\' uygun demektir; şiddet içeren film küçük çocuklara uygun değildir.'),
  ('"The teacher warned us not to be late again." Cümlesinde \'warned\' ne anlama gelir?', 'uyardı', ['ödüllendirdi', 'affetti', 'güldürdü'], '\'Warn\' uyarmak demektir.'),
  ('"Don\'t throw away those bottles; we can recycle them." Cümlesindeki \'throw away\' ne anlama gelir?', 'çöpe atmak', ['fırlatıp kırmak', 'doldurmak', 'yıkayıp kurutmak'], '\'Throw away\' bir şeyi atmak, çöpe atmak demektir.'),
  ('"I grew up in Trabzon, but now I live in Istanbul." Cümlesinde \'grew up\' ne anlama gelir?', 'büyüdüm, çocukluğum geçti', ['orada doğdum ve hemen taşındık', 'orada yalnızca tatil yaptım', 'orada üniversite okudum'], '\'Grow up\' bir yerde büyümek, çocukluğunu geçirmek demektir.'),
  ('"Can I try on these jeans?" sorusunda \'try on\' ne anlama gelir?', 'üzerinde denemek', ['onarmak, diktirmek', 'satın almak', 'başka bir ürünle değiştirmek'], 'Giysiler için \'try on\' bedenine uyup uymadığını görmek için denemek demektir.'),
  ('"The manager gave a brief speech and then we started eating." Cümlesinde \'brief\' yerine hangisi getirilebilir?', 'short', ['boring', 'loud', 'formal and long'], '\'Brief\' kısa demektir; \'short\' bu bağlamda eş anlamlıdır.'),
  ('"The bus seats at the front are for elderly passengers." Cümlesinde \'elderly\' sözcüğünün kibar biçimde anlattığı kişiler kimlerdir?', 'yaşlılar', ['çocuklar', 'engelliler', 'hamileler'], '\'Elderly\' yaşlı demektir ve \'old\' sözcüğünden daha kibar bir kullanımdır.'),
  ('"This street is too narrow for buses." Cümlesinde \'narrow\' sözcüğünün zıttı hangisidir?', 'wide', ['long', 'busy', 'steep'], '\'Narrow\' dar, \'wide\' geniş demektir.'),
