  ('"Let\'s meet at the ____ in the city centre; there are lots of shops inside." Cümlesinde birçok mağazanın bulunduğu kapalı alanı anlatan sözcük hangisidir?', 'shopping centre', ['stadium', 'town hall', 'natural history museum'], 'İçinde birçok mağaza bulunan yer \'shopping centre\' (AVM) dır. \'Town hall\' belediye binasıdır.'),
  ('"There\'s a lovely ____ near my house where children play and people walk their dogs." Boşluğa hangisi gelir?', 'park', ['prison', 'factory', 'harbour'], 'Çocukların oynadığı ve köpek gezdirilen yer parktır.'),
  ('"He whispered something in my ear so that nobody else could hear." Cümlesindeki \'whispered\' ne anlama gelir?', 'fısıldadı', ['bağırdı', 'şarkı söyledi', 'güldü'], '\'Whisper\' başkaları duymasın diye çok alçak sesle konuşmak, fısıldamaktır.'),
  ('"He promised to call me, but he didn\'t." Cümlesinde \'promised\' ne anlama gelir?', 'söz verdi', ['teklifi reddetti', 'unuttu', 'kibarca rica etti'], '\'Promise\' söz vermek demektir.'),
  ('"She apologised for being late." Cümlesindeki \'apologised\' ne anlama gelir?', 'özür diledi', ['şikâyet etti', 'bahane uydurdu', 'teşekkür etti'], '\'Apologise (for)\' bir şey için özür dilemek demektir.'),
  ('"My parents got divorced when I was ten." Cümlesindeki \'got divorced\' ne anlama gelir?', 'boşandılar', ['evlendiler', 'nişanlandılar', 'taşındılar'], '\'Get divorced\' boşanmak demektir; evlenmek \'get married\' tır.'),
