  ('"She applied for a job at the bank." Cümlesindeki \'applied for\' ne anlama gelir?', 'başvurdu', ['istifa etti', 'terfi aldı', 'emekli oldu'], '\'Apply for a job\' bir işe başvurmak demektir.'),
  ('"After ten years, my father retired from his job." Cümlesinde \'retired\' ne anlama gelir?', 'emekli oldu', ['kovuldu', 'terfi etti', 'işe başladı'], '\'Retire\' emekli olmak demektir.'),
